return {name="sure little reed",inspect=function(ctx) local s,i,c,t=ctx.sanity,ctx.insight,ctx.charges,ctx.state; if t==0 then if i>=40 then return "Brass reed, pocket-small. The G is recut over a fainter letter. The dented lip would not sound it." elseif s<50 then return "A small brass reed stamped G. The dent should spoil the note. The letter looks more trustworthy than that." else return "A pocket reed, brass gone dull. Stamped G, as if naming settled pitch. The lip is dented the wrong way." end end; if c==0 then if i>=40 then return "Cold lip, silent. One dent, one later G. Nothing further will test them, and the letter does not mind." else return "The lip has gone cold. The stamp has not. G sits there, sure of a note no breath is left to try." end end; if t<3 then if i>=40 then return "Flat of the stamp, the lip still disagrees. A little warmth on the metal does not make G any truer." elseif s>=80 then return "It has been breathed on. The note was thin. The stamped G has not revised itself, and looks glad of that." else return "A thin breath has crossed it. The dent remains the better evidence. The letter does not concede." end end; if s<40 then return "Same dent, same G. The mismatch has become a manner of speaking. That ease is not in the brass." elseif i>=100 then return "Count the evidence again: one dent, one later stamp, one thin sound. The sure account is only the stamp." else return "Each look makes the wrong letter easier. The reed offers no new proof. Confidence arrives without it." end end,apply=function(ctx) local s,i,c,t=ctx.sanity,ctx.insight,ctx.charges,ctx.state; local n=t+1; if n>255 then n=255 end; local d=0; local text="Air crosses the dent and comes out narrow, not the named note. The stamp does not blush."; if i>=80 then d=1; if c<=1 then text="Cold lip, thin air, still not G. You keep the dent and let the sure letter stand alone." else text="You sound it and refuse the stamp. A flat thread of air, not G. The letter stays certain anyway." end elseif s<35 then d=-2; if t>=2 then text="The name arrives before the sound. G, you think, and the thin air agrees too quickly." else text="The thin note arrives already named. You accept G before the air finishes. The dent does not argue." end elseif s>=70 and i<20 then d=-1; if c<=1 then text="Nearly spent, it still comes out flat. The stamp seems kinder than the dent, and you nearly side with it." else text="A short breath, flatter than G. For a moment the stamp seems the better witness. The dent waits." end elseif t>=3 then d=-1; text="Again the same thin pitch. Calling it G is easier than before. Nothing in the reed improved." elseif c<=1 then text="The last thin air is not G. The letter keeps a confidence the breath never earned." end; return {text=text,state=n,sanity_delta=d} end}